/* assets/three.min.js - local copy placeholder
   NOTE: This is a small wrapper that proxies to CDN if needed; for a real local copy, replace this with an actual minified three.js bundle.
   To keep repo size small in this example, we'll use a tiny loader that writes the CDN content into the page synchronously.
*/
(function(){
  // Attempt to use existing THREE
  if(typeof THREE !== 'undefined') return;
  var s = document.createElement('script');
  s.src = 'https://cdnjs.cloudflare.com/ajax/libs/three.js/r146/three.min.js';
  s.async = false; // load synchronously to ensure availability
  document.head.appendChild(s);
})();
